/**
 * Cloudflare entry point: the OpenNext app plus a timer (see "triggers" in
 * wrangler.jsonc) that runs scheduled jobs every 5 minutes.
 */
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";
import { cronToken } from "./src/lib/cron/auth";

interface Env {
  SUPABASE_SECRET_KEY?: string;
  SUPABASE_SERVICE_ROLE_KEY?: string;
  SITE_URL?: string;
}

const worker = {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const secret = env.SUPABASE_SECRET_KEY ?? env.SUPABASE_SERVICE_ROLE_KEY;
    if (!secret) {
      console.error("[cron] SUPABASE_SECRET_KEY is not set");
      return;
    }
    const req = new Request(`${env.SITE_URL ?? "https://chairvana.app"}/api/cron/messages`, {
      method: "POST",
      headers: { "x-chairvana-cron": await cronToken(secret) },
    });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => {
        if (!res.ok) console.error(`[cron] messages run returned ${res.status}`);
      }),
    );
  },
};

export default worker;

// Durable Object classes the OpenNext build expects to be exported.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
